function attack(){if(!active||dead||attackTimer>0||player.stam<8)return;attackTimer=.28;player.stam-=8;noiseTimer=.6;let hit=false;for(const z of zombies){if(z.dead)continue;let dx=z.x-player.x,dy=z.y-player.y,d=Math.hypot(dx,dy),dot=(dx*player.dirX+dy*player.dirY)/(d||1);if(d<55&&dot>-.15){z.hp--;z.alert=7;z.state='chase';z.x+=player.dirX*12;z.y+=player.dirY*12;hit=true;if(z.hp<=0){z.dead=true;log('<strong>Infected</strong> put down.','good');if(Math.random()<.25)items.push({x:z.x,y:z.y,type:'bandage',taken:false,building:'INFECTED'})}else log('<strong>Hit landed.</strong> It’s still coming.','warn')}}if(!hit){log('<strong>Swing</strong> cut through empty air.','warn');for(const z of zombies)if(!z.dead&&distance(z.x,z.y,player.x,player.y)<210){z.alert=5;z.state='chase'}}}
