function useItem(){if(!active||!inventory.length)return;let idx=inventory.findIndex(i=>['water','canned','snack','bandage'].includes(i.type));if(idx<0){notify('NOTHING USABLE IN YOUR PACK');return}let it=inventory[idx];if(it.type==='water')player.thirst=Math.min(100,player.thirst+38);if(it.type==='canned'||it.type==='snack')player.hunger=Math.min(100,player.hunger+(it.type==='canned'?32:22));if(it.type==='bandage')player.hp=Math.min(100,player.hp+35);it.count--;if(it.count<=0)inventory.splice(idx,1);renderInventory();notify(it.type==='water'?'YOU DRANK SOME WATER':it.type==='bandage'?'WOUNDS BANDED':'YOU ATE SOMETHING');log(`<strong>Used ${itemDefs[it.type].name.toLowerCase()}.</strong>`,'good')}

