1: (()=>{'use strict';
2: const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d'), mini=document.getElementById('miniMap'),mx=mini.getContext('2d');
3: const $=id=>document.getElementById(id); const W=1900,H=1350, TILE=48;
4: let active=false,dead=false,last=0,elapsed=0,dayMinute=450,toastTimer=0,attackTimer=0,noiseTimer=0,anim=0;
5: const player={x:930,y:670,r:11,hp:100,stam:100,hunger:100,thirst:100,dirX:0,dirY:1,speed:122,invuln:0};
6: let items=[],zombies=[],decor=[],buildings=[],inventory=[],keys={},mobile={},events=[];
7: const itemDefs={water:{name:'WATER',icon:'◒',color:'#82b8bd',count:1},canned:{name:'CANNED FOOD',icon:'▣',color:'#d2b979',count:1},bandage:{name:'BANDAGE',icon:'✚',color:'#d6ddd0',count:1},knife:{name:'HUNTING KNIFE',icon:'†',color:'#bec3a7',count:1},ammo:{name:'AMMO',icon:'▪',color:'#c69b58',count:1},snack:{name:'SNACK',icon:'◈',color:'#c89466',count:1}};
8: const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
9: function initWorld(){
10:   buildings=[{x:210,y:180,w:260,h:175,type:'house',name:'MORGAN RESIDENCE',color:'#827a60'},{x:590,y:150,w:320,h:200,type:'market',name:'QUICKMART',color:'#81765a'},{x:1120,y:180,w:250,h:175,type:'house',name:'RANCH HOUSE',color:'#766e58'},{x:1500,y:160,w:270,h:200,type:'house',name:'FARMHOUSE',color:'#86765c'},{x:230,y:510,w:290,h:190,type:'diner',name:'MEL’S DINER',color:'#8b715b'},{x:660,y:500,w:210,h:180,type:'house',name:'COTTAGE',color:'#766b57'},{x:1060,y:500,w:300,h:200,type:'pharmacy',name:'RAVEN PHARMACY',color:'#79755c'},{x:1510,y:510,w:260,h:180,type:'house',name:'COLONIAL',color:'#82755c'},{x:200,y:910,w:280,h:220,type:'house',name:'CREEKSIDE HOME',color:'#776c56'},{x:620,y:900,w:280,h:190,type:'warehouse',name:'AUTO REPAIR',color:'#746e56'},{x:1090,y:910,w:250,h:190,type:'house',name:'SPLIT LEVEL',color:'#82735b'},{x:1510,y:920,w:270,h:205,type:'house',name:'HILLTOP HOME',color:'#82775e'}];
11:   // Intersecting asphalt streets leave broad strips of walkable grass.
12:   decor=[];let seed=83;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
13:   for(let i=0;i<100;i++){let x=rand(35,W-35),y=rand(35,H-35);if(!nearBuilding(x,y,65)&&Math.abs(y-430)>52&&Math.abs(y-810)>52&&Math.abs(x-980)>54)decor.push({x,y,type:random()<.76?'tree':'bush',s:rand(.7,1.35),tone:Math.floor(random()*4)});}
14:   for(const b of buildings){let candidates=[];for(let i=0;i<2;i++){let x=b.x+rand(45,b.w-35),y=b.y+rand(60,b.h-28);if(!nearRoad(x,y,30))candidates.push({x,y});}if(candidates.length)items.push({x:candidates[0].x,y:candidates[0].y,type:pickType(b.type),taken:false,building:b.name});}
15:   // A few visible roadside finds reward wandering beyond buildings.
16:   [[960,445,'water'],[1000,790,'bandage'],[535,760,'canned'],[1400,800,'snack'],[960,520,'knife']].forEach(([x,y,type])=>items.push({x,y,type,taken:false,building:'STREET FIND'}));
17:   zombies=[];for(let i=0;i<19;i++){let x,y,tries=0;do{x=rand(60,W-60);y=rand(60,H-60);tries++;}while((nearBuilding(x,y,20)||nearRoad(x,y,30)||distance(x,y,player.x,player.y)<180)&&tries<40);zombies.push({x,y,r:10,dir:rand(0,6.2),speed:rand(15,26),alert:0,hp:2,state:'wander',wander:rand(1,4),attack:0,dead:false});}
18: }
19: function pickType(t){let a=t==='market'?['canned','water','snack','ammo']:t==='pharmacy'?['bandage','water','bandage']:t==='diner'?['canned','snack','water']:t==='warehouse'?['knife','ammo','water']:['water','canned','bandage','snack'];return a[Math.floor(Math.random()*a.length)]}
20: function nearBuilding(x,y,p=0){return buildings.some(b=>x>b.x-p&&x<b.x+b.w+p&&y>b.y-p&&y<b.y+b.h+p)}
21: function nearRoad(x,y,p=0){return Math.abs(y-430)<38+p||Math.abs(y-810)<38+p||Math.abs(x-980)<40+p}
22: function distance(x,y,a,b){return Math.hypot(x-a,y-b)}
23: function log(text,type=''){events.unshift({text,time:clockText(),type});events=events.slice(0,6);renderLog()}
